const ExcelJS = require('exceljs');

async function main() {
  const workbook = new ExcelJS.Workbook();
  const sheet = workbook.addWorksheet('Invoice');

  // Header row
  sheet.columns = [
    { header: 'Field', key: 'field', width: 20 },
    { header: 'Value', key: 'value', width: 25 },
  ];

  // Style the header
  sheet.getRow(1).font = { bold: true };

  // Data extracted from invoice.png
  sheet.addRow({ field: 'Invoice #', value: '1042' });
  sheet.addRow({ field: 'Date',      value: '2026-08-01' });
  sheet.addRow({ field: 'Total',     value: '$2500.00' });

  await workbook.xlsx.writeFile('/workspace/invoice.xlsx');
  console.log('Created /workspace/invoice.xlsx');
}

main().catch(console.error);
